insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k001', 'mcq', 'ISA', 1, 1, null, 2, '0'::jsonb, '{"q":"How many prophets of the Old Testament wrote a book that bears their name?","options":["16","17","12","22"],"explain":"4 major prophets (Isaiah, Jeremiah, Ezekiel, Daniel) and 12 minor prophets (Hosea to Malachi)."}'::jsonb, '{"q":"பழைய ஏற்பாட்டில் தங்கள் பெயரில் புஸ்தகம் எழுதிய தீர்க்கதரிசிகள் எத்தனை பேர்?","options":["16","17","12","22"],"explain":"4 பெரிய தீர்க்கதரிசிகள் (ஏசாயா, எரேமியா, எசேக்கியேல், தானியேல்), 12 சிறிய தீர்க்கதரிசிகள் (ஓசியா முதல் மல்கியா வரை)."}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k002', 'mcq', '1KI', 17, 1, null, 2, '3'::jsonb, '{"q":"Which of these prophets did NOT write a book of the Bible?","options":["Malachi","Isaiah","Jonah","Elijah"]}'::jsonb, '{"q":"இவர்களில் வேதாகமப் புஸ்தகம் எழுதாத தீர்க்கதரிசி யார்?","options":["மல்கியா","ஏசாயா","யோனா","எலியா"]}'::jsonb, 'altar', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k003', 'mcq', 'PSA', 72, 20, null, 2, '1'::jsonb, '{"q":"By the psalm titles, about how many psalms are of David?","options":["12","73","150","50"],"explain":"73 psalms carry David''s name in their titles; counting Psalms 2 and 95 (Acts 4:25, Hebrews 4:7) some say 75."}'::jsonb, '{"q":"சங்கீதங்களின் தலைப்புகளின்படி தாவீதின் சங்கீதங்கள் ஏறக்குறைய எத்தனை?","options":["12","73","150","50"],"explain":"73 சங்கீதங்களின் தலைப்பில் தாவீதின் பெயர் உள்ளது; 2, 95 ஆம் சங்கீதங்களையும் சேர்த்து (அப். 4:25, எபி. 4:7) சிலர் 75 என்பர்."}'::jsonb, 'harp', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k004', 'mcq', 'PSA', 73, 1, null, 2, '0'::jsonb, '{"q":"How many psalms are of Asaph?","options":["12","24","3","7"],"explain":"Psalm 50 and Psalms 73 to 83."}'::jsonb, '{"q":"ஆசாபின் சங்கீதங்கள் எத்தனை?","options":["12","24","3","7"],"explain":"50 ஆம் சங்கீதமும், 73 முதல் 83 வரையிலான சங்கீதங்களும்."}'::jsonb, 'harp', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k005', 'mcq', 'PSA', 127, 1, null, 2, '1'::jsonb, '{"q":"How many psalms are of Solomon?","options":["1","2","5","10"],"explain":"Psalm 72 and Psalm 127."}'::jsonb, '{"q":"சாலொமோனின் சங்கீதங்கள் எத்தனை?","options":["1","2","5","10"],"explain":"72 ஆம் சங்கீதமும் 127 ஆம் சங்கீதமும்."}'::jsonb, 'harp', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k006', 'mcq', 'ECC', 1, 1, null, 2, '1'::jsonb, '{"q":"Which of these books did Solomon write?","options":["Job","Ecclesiastes","Ruth","Lamentations"],"explain":"Solomon wrote Proverbs, Ecclesiastes, the Song of Solomon and two psalms."}'::jsonb, '{"q":"இவற்றில் சாலொமோன் எழுதிய புஸ்தகம் எது?","options":["யோபு","பிரசங்கி","ரூத்","புலம்பல்"],"explain":"நீதிமொழிகள், பிரசங்கி, உன்னதப்பாட்டு, இரண்டு சங்கீதங்கள் ஆகியவற்றைச் சாலொமோன் எழுதினார்."}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k007', 'mcq', 'PRO', 1, 1, null, 2, '0'::jsonb, '{"q":"Who wrote most of the book of Proverbs?","options":["Solomon","Moses","David","Asaph"]}'::jsonb, '{"q":"நீதிமொழிகள் புஸ்தகத்தின் பெரும்பகுதியை எழுதியவர் யார்?","options":["சாலொமோன்","மோசே","தாவீது","ஆசாப்"]}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k008', 'mcq', 'JER', 36, 4, null, 2, '3'::jsonb, '{"q":"Who was Jeremiah''s helper who wrote down his words?","options":["Barak","Gehazi","Elisha","Baruch"],"explain":"Baruch the son of Neriah wrote from the mouth of Jeremiah. (Barak was a judge with Deborah.)"}'::jsonb, '{"q":"எரேமியாவின் வார்த்தைகளை எழுதிய அவருடைய உதவியாளர் யார்?","options":["பாராக்","கேயாசி","எலிசா","பாருக்கு"],"explain":"நேரியாவின் குமாரனாகிய பாருக்கு எரேமியாவின் வாய்மொழியின்படி எழுதினான். (பாராக் தெபொராளுடன் இருந்த நியாயாதிபதி.)"}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k009', 'mcq', 'LEV', 1, 1, null, 2, '0'::jsonb, '{"q":"Which of these books was written by Moses?","options":["Leviticus","Joshua","Ruth","Judges"],"explain":"Moses wrote Genesis, Exodus, Leviticus, Numbers and Deuteronomy."}'::jsonb, '{"q":"இவற்றில் மோசே எழுதிய புஸ்தகம் எது?","options":["லேவியராகமம்","யோசுவா","ரூத்","நியாயாதிபதிகள்"],"explain":"ஆதியாகமம், யாத்திராகமம், லேவியராகமம், எண்ணாகமம், உபாகமம் ஆகியவற்றை மோசே எழுதினார்."}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k010', 'mcq', 'PSA', 90, 1, null, 2, '0'::jsonb, '{"q":"Which psalm is \"A Prayer of Moses the man of God\"?","options":["Psalm 90","Psalm 119","Psalm 23","Psalm 51"]}'::jsonb, '{"q":"\"தேவனுடைய மனுஷனாகிய மோசேயின் ஜெபம்\" எந்தச் சங்கீதம்?","options":["90 ஆம் சங்கீதம்","119 ஆம் சங்கீதம்","23 ஆம் சங்கீதம்","51 ஆம் சங்கீதம்"]}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k011', 'mcq', 'JOB', 1, 1, null, 2, '0'::jsonb, '{"q":"Besides the five books of the Law, which book is traditionally said to be written by Moses?","options":["Job","Esther","Judges","Joshua"]}'::jsonb, '{"q":"நியாயப்பிரமாணத்தின் ஐந்து புஸ்தகங்களைத் தவிர, மோசே எழுதியதாகப் பாரம்பரியமாகச் சொல்லப்படும் புஸ்தகம் எது?","options":["யோபு","எஸ்தர்","நியாயாதிபதிகள்","யோசுவா"]}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k012', 'mcq', '1CH', 29, 29, null, 2, '2'::jsonb, '{"q":"Which books are traditionally said to be written by Samuel?","options":["Ezra and Nehemiah","1 and 2 Kings","Judges, Ruth and part of 1 Samuel","Esther and Job"],"explain":"The rest of the acts of David were written by Samuel the seer, Nathan the prophet and Gad the seer."}'::jsonb, '{"q":"சாமுவேல் எழுதியதாகப் பாரம்பரியமாகச் சொல்லப்படும் புஸ்தகங்கள் எவை?","options":["எஸ்றா, நெகேமியா","1, 2 இராஜாக்கள்","நியாயாதிபதிகள், ரூத், 1 சாமுவேலின் ஒரு பகுதி","எஸ்தர், யோபு"],"explain":"தாவீதின் மற்ற வர்த்தமானங்களை ஞானதிருஷ்டிக்காரனாகிய சாமுவேலும், தீர்க்கதரிசியாகிய நாத்தானும், ஞானதிருஷ்டிக்காரனாகிய காத்தும் எழுதினார்கள்."}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k013', 'mcq', '1CH', 29, 29, null, 2, '1'::jsonb, '{"q":"Together with Samuel, which two prophets wrote down the acts of David?","options":["Elijah and Elisha","Nathan and Gad","Haggai and Zechariah","Isaiah and Jeremiah"]}'::jsonb, '{"q":"சாமுவேலுடன் சேர்ந்து தாவீதின் வர்த்தமானங்களை எழுதிய இரண்டு தீர்க்கதரிசிகள் யார்?","options":["எலியா, எலிசா","நாத்தான், காத்","ஆகாய், சகரியா","ஏசாயா, எரேமியா"]}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k014', 'mcq', 'ROM', 1, 1, null, 2, '2'::jsonb, '{"q":"Counting Hebrews, how many letters are traditionally said to be written by Paul?","options":["7","12","14","21"],"explain":"Romans to Philemon are 13 letters; with Hebrews, 14."}'::jsonb, '{"q":"எபிரெயரையும் சேர்த்து, பவுல் எழுதியதாகச் சொல்லப்படும் நிருபங்கள் எத்தனை?","options":["7","12","14","21"],"explain":"ரோமர் முதல் பிலேமோன் வரை 13 நிருபங்கள்; எபிரெயரையும் சேர்த்து 14."}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k015', 'mcq', 'ROM', 1, 7, null, 2, '2'::jsonb, '{"q":"To churches in how many different places did Paul write (Romans to 2 Thessalonians)?","options":["9","3","7","12"],"explain":"Rome, Corinth, Galatia, Ephesus, Philippi, Colosse and Thessalonica."}'::jsonb, '{"q":"பவுல் எத்தனை வெவ்வேறு இடங்களிலுள்ள சபைகளுக்கு நிருபம் எழுதினார் (ரோமர் முதல் 2 தெசலோனிக்கேயர் வரை)?","options":["9","3","7","12"],"explain":"ரோமா, கொரிந்து, கலாத்தியா, எபேசு, பிலிப்பி, கொலோசெ, தெசலோனிக்கே."}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k016', 'mcq', 'PHM', 1, 1, null, 2, '2'::jsonb, '{"q":"Which of these New Testament letters was written to one person?","options":["Galatians","Hebrews","Philemon","Ephesians"],"explain":"1 and 2 Timothy, Titus and Philemon were written to one person; so were 2 John (the elect lady) and 3 John (Gaius)."}'::jsonb, '{"q":"இவற்றில் ஒரு தனி நபருக்கு எழுதப்பட்ட புதிய ஏற்பாட்டு நிருபம் எது?","options":["கலாத்தியர்","எபிரெயர்","பிலேமோன்","எபேசியர்"],"explain":"1, 2 தீமோத்தேயு, தீத்து, பிலேமோன் ஆகியவை தனி நபருக்கு எழுதப்பட்டவை; 2 யோவான் (அம்மாள்), 3 யோவான் (காயு) கூட."}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k017', 'mcq', '2JN', 1, 1, null, 2, '3'::jsonb, '{"q":"To whom was the second letter of John written?","options":["Timothy","Gaius","The church at Rome","The elect lady and her children"]}'::jsonb, '{"q":"யோவான் எழுதிய இரண்டாம் நிருபம் யாருக்கு எழுதப்பட்டது?","options":["தீமோத்தேயுவுக்கு","காயுவுக்கு","ரோமாவிலுள்ள சபைக்கு","தெரிந்துகொள்ளப்பட்ட அம்மாளுக்கும் அவள் பிள்ளைகளுக்கும்"]}'::jsonb, 'writer', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k018', 'mcq', 'MAT', 10, 2, null, 2, '0'::jsonb, '{"q":"Which of these was NOT one of the twelve disciples of Jesus?","options":["Barnabas","Thaddaeus","Bartholomew","Simon the Canaanite"],"explain":"Peter, Andrew, James, John, Philip, Bartholomew, Thomas, Matthew, James son of Alphaeus, Thaddaeus, Simon the Canaanite and Judas Iscariot."}'::jsonb, '{"q":"இவர்களில் இயேசுவின் பன்னிரண்டு சீஷரில் ஒருவர் அல்லாதவர் யார்?","options":["பர்னபா","ததேயு","பற்தொலொமேயு","கானானியனாகிய சீமோன்"],"explain":"பேதுரு, அந்திரேயா, யாக்கோபு, யோவான், பிலிப்பு, பற்தொலொமேயு, தோமா, மத்தேயு, அல்பேயுவின் குமாரனாகிய யாக்கோபு, ததேயு, கானானியனாகிய சீமோன், யூதாஸ்காரியோத்து."}'::jsonb, 'boat', array['knowledge']::text[], 'published')
