insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k030', 'mcq', 'GEN', 1, 26, null, 2, '3'::jsonb, '{"q":"For what purpose did God make man in His image and give him dominion?","options":["Only to name the animals","Only to keep the garden","To rest every day","To express God and to represent Him"]}'::jsonb, '{"q":"தேவன் மனுஷனைத் தம்முடைய சாயலாக உண்டாக்கி ஆளுகை கொடுத்ததின் நோக்கம் என்ன?","options":["மிருகங்களுக்குப் பெயரிட மட்டும்","தோட்டத்தைக் காக்க மட்டும்","தினமும் ஓய்வெடுக்க","தேவனை வெளிப்படுத்தவும் அவரைப் பிரதிநிதித்துவப்படுத்தவும்"]}'::jsonb, 'sun', array['knowledge']::text[], 'published')
