insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k033', 'mcq', 'GEN', 1, 24, null, 2, '1'::jsonb, '{"q":"What did God make on the sixth day?","options":["The sun, moon and stars","Cattle, creeping things, beasts of the earth, and man","Grass, herbs and trees","Fish and birds"]}'::jsonb, '{"q":"ஆறாம் நாளில் தேவன் எவைகளை உண்டாக்கினார்?","options":["சூரியன், சந்திரன், நட்சத்திரங்கள்","நாட்டுமிருகங்கள், ஊரும் பிராணிகள், காட்டுமிருகங்கள், மனுஷன்","புல், பூண்டு, மரங்கள்","மீன்களும் பறவைகளும்"]}'::jsonb, 'sun', array['knowledge']::text[], 'published')
