insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k047', 'mcq', 'GEN', 7, 4, null, 2, '3'::jsonb, '{"q":"When do we first read of rain falling on the earth?","options":["In the days of Adam","In the days of Abraham","In the days of Moses","In the days of Noah"],"explain":"Before that, a mist went up from the earth and watered the ground (Genesis 2:5-6)."}'::jsonb, '{"q":"பூமியின்மேல் மழை பெய்ததைப்பற்றி முதன்முதலில் எப்போது வாசிக்கிறோம்?","options":["ஆதாமின் நாட்களில்","ஆபிரகாமின் நாட்களில்","மோசேயின் நாட்களில்","நோவாவின் நாட்களில்"],"explain":"அதற்கு முன் பூமியிலிருந்து மூடுபனி எழும்பி, பூமியை நனைத்தது (ஆதி. 2:5-6)."}'::jsonb, 'ark', array['knowledge']::text[], 'published')
