insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k059', 'mcq', 'GEN', 8, 14, null, 2, '2'::jsonb, '{"q":"About how long were Noah and his family in the ark?","options":["Three years","40 days","About a year","7 days"],"explain":"They went in during the 600th year, 2nd month, 17th day (7:11) and the earth was dry in the 601st year, 2nd month, 27th day."}'::jsonb, '{"q":"நோவாவும் அவன் குடும்பமும் ஏறக்குறைய எவ்வளவு காலம் பேழைக்குள் இருந்தார்கள்?","options":["மூன்று வருஷம்","40 நாள்","ஏறக்குறைய ஒரு வருஷம்","7 நாள்"],"explain":"600 ஆம் வருஷம் 2 ஆம் மாதம் 17 ஆம் தேதி உள்ளே சென்றார்கள் (7:11); 601 ஆம் வருஷம் 2 ஆம் மாதம் 27 ஆம் தேதி பூமி காய்ந்தது."}'::jsonb, 'ark', array['knowledge']::text[], 'published')
