insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k062', 'mcq', 'GEN', 10, 10, null, 2, '2'::jsonb, '{"q":"Which of these cities was in the beginning of Nimrod''s kingdom?","options":["Damascus","Sodom","Erech","Hebron"],"explain":"Babel, Erech, Accad and Calneh, in the land of Shinar."}'::jsonb, '{"q":"இவற்றில் நிம்ரோதின் ராஜ்யத்தின் ஆரம்ப பட்டணம் எது?","options":["தமஸ்கு","சோதோம்","ஏரேக்","எபிரோன்"],"explain":"சிநேயார் தேசத்திலுள்ள பாபேல், ஏரேக், அக்காத், கல்னே."}'::jsonb, 'tower', array['knowledge']::text[], 'published')
