insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k070', 'mcq', 'GEN', 12, 1, null, 2, '3'::jsonb, '{"q":"What did God tell Abram to leave?","options":["His flocks and herds","Only his idols","His wife and his nephew","His country, his kindred and his father''s house"]}'::jsonb, '{"q":"ஆபிராமை எவைகளை விட்டுப் புறப்படும்படி தேவன் சொன்னார்?","options":["தன் ஆடுமாடுகளை","தன் விக்கிரகங்களை மட்டும்","தன் மனைவியையும் சகோதரன் மகனையும்","தன் தேசத்தையும், தன் இனத்தையும், தன் தகப்பன் வீட்டையும்"]}'::jsonb, 'tent', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k071', 'mcq', 'GEN', 12, 7, null, 2, '2'::jsonb, '{"q":"Where did the LORD first say to Abram, \"Unto thy seed will I give this land\"?","options":["Bethel","Hebron","Sichem, at the plain of Moreh","Ur of the Chaldees"]}'::jsonb, '{"q":"\"உன் சந்ததிக்கு இந்தத் தேசத்தைக் கொடுப்பேன்\" என்று கர்த்தர் ஆபிராமிடம் முதலில் சொன்ன இடம் எது?","options":["பெத்தேல்","எபிரோன்","சீகேம், மோரே என்னும் சமபூமி","கல்தேயரின் ஊர்"]}'::jsonb, 'tent', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k072', 'mcq', 'GEN', 13, 8, null, 2, '2'::jsonb, '{"q":"What did Abram say to Lot when their herdmen strove?","options":["Go back to Haran","Take all the cattle","Let there be no strife between me and thee, for we be brethren","Let us never meet again"]}'::jsonb, '{"q":"மேய்ப்பர்கள் வாக்குவாதம் செய்தபோது ஆபிராம் லோத்திடம் என்ன சொன்னான்?","options":["ஆரானுக்குத் திரும்பிப்போ","எல்லா மிருகஜீவன்களையும் எடுத்துக்கொள்","எனக்கும் உனக்கும் வாக்குவாதம் வேண்டாம்; நாம் சகோதரர்","இனி ஒருபோதும் சந்திக்கவேண்டாம்"]}'::jsonb, 'sheep', array['knowledge']::text[], 'published')
