insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k074', 'mcq', 'GEN', 15, 2, null, 2, '3'::jsonb, '{"q":"Whom did Abram first think would be his heir?","options":["Nahor","Lot","Ishmael","Eliezer of Damascus"]}'::jsonb, '{"q":"தன் சுதந்தரவாளியாக ஆபிராம் முதலில் நினைத்தது யாரை?","options":["நாகோர்","லோத்து","இஸ்மவேல்","தமஸ்கு ஊரானாகிய எலியேசர்"]}'::jsonb, 'tent', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k075', 'mcq', 'GEN', 15, 13, null, 2, '1'::jsonb, '{"q":"God told Abram his seed would be afflicted in a strange land for how many years?","options":["40 years","400 years","70 years","100 years"]}'::jsonb, '{"q":"ஆபிராமின் சந்ததி அந்நிய தேசத்தில் எத்தனை வருஷம் உபத்திரவப்படுவார்கள் என்று தேவன் சொன்னார்?","options":["40 வருஷம்","400 வருஷம்","70 வருஷம்","100 வருஷம்"]}'::jsonb, 'stars', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k076', 'mcq', 'GEN', 15, 16, null, 2, '0'::jsonb, '{"q":"Why would Abram''s seed come back only in the fourth generation?","options":["The iniquity of the Amorites was not yet full","They first had to learn the law","Pharaoh would not let them go","The land was too small"]}'::jsonb, '{"q":"ஆபிராமின் சந்ததி நான்காம் தலைமுறையில்தான் திரும்பி வருவார்கள்; ஏன்?","options":["எமோரியருடைய அக்கிரமம் இன்னும் நிறைவாகவில்லை","முதலில் நியாயப்பிரமாணத்தைக் கற்கவேண்டும்","பார்வோன் அவர்களைப் போகவிடமாட்டான்","தேசம் மிகச் சிறியது"]}'::jsonb, 'stars', array['knowledge']::text[], 'published')
