insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k108', 'mcq', 'GEN', 31, 22, null, 2, '0'::jsonb, '{"q":"On which day was it told Laban that Jacob had fled?","options":["The third day","The seventh day","The first day","The tenth day"]}'::jsonb, '{"q":"யாக்கோபு ஓடிப்போனான் என்று எத்தனையாம் நாளில் லாபானுக்கு அறிவிக்கப்பட்டது?","options":["மூன்றாம் நாள்","ஏழாம் நாள்","முதலாம் நாள்","பத்தாம் நாள்"]}'::jsonb, 'camel', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k109', 'mcq', 'GEN', 31, 23, null, 2, '1'::jsonb, '{"q":"After how many days'' journey, and where, did Laban overtake Jacob?","options":["Three days, at Bethel","Seven days, in the mount Gilead","Forty days, at Haran","Ten days, at Shechem"]}'::jsonb, '{"q":"லாபான் எத்தனை நாள் பிரயாணம்பண்ணி, எங்கே யாக்கோபைப் பிடித்தான்?","options":["மூன்று நாள், பெத்தேலில்","ஏழு நாள், கீலேயாத் மலையில்","நாற்பது நாள், ஆரானில்","பத்து நாள், சீகேமில்"]}'::jsonb, 'camel', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k110', 'mcq', 'GEN', 31, 34, null, 2, '0'::jsonb, '{"q":"Who stole Laban''s images, and where were they hidden?","options":["Rachel, in the camel''s furniture","Dinah, under an oak","Leah, in her tent","Rachel, in a well"]}'::jsonb, '{"q":"லாபானின் சுரூபங்களைத் திருடியது யார், எங்கே ஒளித்துவைத்தாள்?","options":["ராகேல், ஒட்டகச் சேணத்தின் கீழ்","தீனாள், கர்வாலிமரத்தின் கீழ்","லேயாள், தன் கூடாரத்தில்","ராகேல், ஒரு கிணற்றில்"]}'::jsonb, 'camel', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k111', 'mcq', 'GEN', 31, 47, null, 2, '3'::jsonb, '{"q":"What did Jacob call the heap of stones?","options":["Jegar-sahadutha","Bethel","Peniel","Galeed"],"explain":"Laban called it Jegar-sahadutha; the place was also called Mizpah."}'::jsonb, '{"q":"கற்குவியலுக்கு யாக்கோபு இட்ட பெயர் என்ன?","options":["ஜெகர்சகதுதா","பெத்தேல்","பெனியேல்","கலயெத்"],"explain":"லாபான் அதற்கு ஜெகர்சகதுதா என்று பெயரிட்டான்; அந்த இடம் மிஸ்பா என்றும் அழைக்கப்பட்டது."}'::jsonb, 'stones', array['knowledge']::text[], 'published')
