insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k113', 'mcq', 'GEN', 31, 49, null, 2, '3'::jsonb, '{"q":"What did Laban say when the place was called Mizpah?","options":["The LORD hath heard","I have seen God face to face","This is the house of God","The LORD watch between me and thee"]}'::jsonb, '{"q":"அந்த இடத்திற்கு மிஸ்பா என்று பெயரிட்டபோது லாபான் சொன்னது என்ன?","options":["கர்த்தர் கேட்டார்","தேவனை முகமுகமாய்க் கண்டேன்","இது தேவனுடைய வீடு","நாம் ஒருவரையொருவர் விட்டுப் பிரிந்திருக்கும்போது கர்த்தர் எனக்கும் உனக்கும் நடுவாக இருந்து காவல்பண்ணுவாராக"]}'::jsonb, 'stones', array['knowledge']::text[], 'published')
