insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k125', 'mcq', 'GEN', 35, 4, null, 2, '1'::jsonb, '{"q":"Where did Jacob hide the strange gods of his household?","options":["On mount Gilead","Under the oak which was by Shechem","In the river Jabbok","At Bethel, under the altar"]}'::jsonb, '{"q":"தன் வீட்டாரிடமிருந்த அந்நிய தேவர்களை யாக்கோபு எங்கே புதைத்தான்?","options":["கீலேயாத் மலையில்","சீகேமுக்கு அருகேயுள்ள கர்வாலிமரத்தின் கீழ்","யாபோக்கு ஆற்றில்","பெத்தேலில் பலிபீடத்தின் கீழ்"]}'::jsonb, 'tree', array['knowledge']::text[], 'published')
