insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k127', 'mcq', 'GEN', 35, 8, null, 2, '1'::jsonb, '{"q":"Where was Deborah, Rebekah''s nurse, buried?","options":["In Hebron","Under an oak below Bethel, called Allon-bachuth","In the cave of Machpelah","On the way to Ephrath"]}'::jsonb, '{"q":"ரெபெக்காளின் தாதியாகிய தெபொராள் எங்கே அடக்கம்பண்ணப்பட்டாள்?","options":["எபிரோனில்","பெத்தேலுக்குக் கீழே அல்லோன்பாகூத் என்னும் கர்வாலிமரத்தின் கீழ்","மக்பேலா குகையில்","எப்பிராத்தாவுக்குப் போகிற வழியில்"]}'::jsonb, 'tree', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k128', 'mcq', 'GEN', 36, 7, null, 2, '1'::jsonb, '{"q":"Whose riches were more than that they might dwell together, so the land could not bear them (Genesis 36:7)?","options":["Isaac and Ishmael","Esau and Jacob","Jacob and Laban","Joseph and his brothers"]}'::jsonb, '{"q":"\"அவர்களுடைய சம்பத்து மிகுதியாயிருந்தபடியினால் அவர்கள் ஒருமித்துக் குடியிருக்கக்கூடாமற்போயிற்று\" (ஆதி. 36:7) — யார்?","options":["ஈசாக்கு, இஸ்மவேல்","ஏசா, யாக்கோபு","யாக்கோபு, லாபான்","யோசேப்பும் அவன் சகோதரரும்"]}'::jsonb, 'sheep', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k130', 'mcq', 'GEN', 37, 9, null, 2, '0'::jsonb, '{"q":"What were Joseph''s two dreams?","options":["Sheaves bowing to his sheaf; the sun, moon and eleven stars bowing to him","A vine with three branches","A ladder reaching to heaven","Seven fat and seven lean cows"]}'::jsonb, '{"q":"யோசேப்பு கண்ட இரண்டு சொப்பனங்கள் என்ன?","options":["அரிக்கட்டுகள் அவனுடைய அரிக்கட்டை வணங்கின; சூரியனும் சந்திரனும் பதினொரு நட்சத்திரங்களும் அவனை வணங்கின","மூன்று கொடிகளுள்ள திராட்சச்செடி","வானத்தை எட்டின ஏணி","ஏழு கொழுத்த பசுக்களும் ஏழு கேவலமான பசுக்களும்"]}'::jsonb, 'sheaves', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k131', 'mcq', 'GEN', 37, 21, null, 2, '2'::jsonb, '{"q":"Who saved Joseph from being killed by his brothers?","options":["Benjamin","Judah","Reuben","Levi"]}'::jsonb, '{"q":"சகோதரர் யோசேப்பைக் கொல்லாதபடி தப்புவித்தவன் யார்?","options":["பென்யமீன்","யூதா","ரூபன்","லேவி"]}'::jsonb, 'coat', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k132', 'mcq', 'GEN', 37, 27, null, 2, '2'::jsonb, '{"q":"Who said, \"Come, and let us sell him to the Ishmeelites\"?","options":["Dan","Simeon","Judah","Reuben"]}'::jsonb, '{"q":"\"அவனை இஸ்மவேலருக்கு விற்றுப்போடுவோம் வாருங்கள்\" என்று சொன்னவன் யார்?","options":["தாண்","சிமியோன்","யூதா","ரூபன்"]}'::jsonb, 'coat', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k133', 'mcq', 'GEN', 37, 28, null, 2, '3'::jsonb, '{"q":"For how many pieces of silver was Joseph sold?","options":["10","30","400","20"]}'::jsonb, '{"q":"யோசேப்பு எத்தனை வெள்ளிக்காசுக்கு விற்கப்பட்டான்?","options":["10","30","400","20"]}'::jsonb, 'coins', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k134', 'mcq', 'GEN', 37, 2, null, 2, '1'::jsonb, '{"q":"How old was Joseph when he was feeding the flock and was sold?","options":["20","17","12","30"]}'::jsonb, '{"q":"மந்தையை மேய்த்துக்கொண்டிருந்து விற்கப்பட்டபோது யோசேப்புக்கு எத்தனை வயது?","options":["20","17","12","30"]}'::jsonb, 'coat', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k135', 'mcq', 'GEN', 37, 31, null, 2, '1'::jsonb, '{"q":"In whose blood did the brothers dip Joseph''s coat?","options":["A lamb","A kid of the goats","A bullock","A dove"]}'::jsonb, '{"q":"யோசேப்பின் அங்கியைச் சகோதரர் எதின் இரத்தத்தில் தோய்த்தார்கள்?","options":["ஆட்டுக்குட்டியின் இரத்தம்","வெள்ளாட்டுக்குட்டியின் இரத்தம்","காளையின் இரத்தம்","புறாவின் இரத்தம்"]}'::jsonb, 'coat', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k136', 'mcq', 'GEN', 38, 25, null, 2, '3'::jsonb, '{"q":"\"Discern, whose are these?\" What did Tamar send to Judah?","options":["Joseph''s coat","A ring and a robe","A silver cup","The signet, the bracelets and the staff"],"explain":"These words come twice: with Joseph''s coat (37:32) and with Judah''s pledge (38:25)."}'::jsonb, '{"q":"\"இவைகள் யாருடையவைகள் என்று பாரும்\" — தாமார் யூதாவுக்கு அனுப்பினது என்ன?","options":["யோசேப்பின் அங்கி","மோதிரமும் அங்கியும்","வெள்ளிப் பாத்திரம்","முத்திரை மோதிரம், ஆரம், கோல்"],"explain":"இந்த வார்த்தைகள் இருமுறை வருகின்றன: யோசேப்பின் அங்கியோடு (37:32), யூதாவின் அடைமானத்தோடு (38:25)."}'::jsonb, 'ring', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k137', 'mcq', 'GEN', 40, 2, null, 2, '0'::jsonb, '{"q":"Who were in prison with Joseph?","options":["Pharaoh''s chief butler and chief baker","Potiphar and his wife","Two priests of On","Two of his brothers"]}'::jsonb, '{"q":"யோசேப்போடு காவலில் இருந்தவர்கள் யார்?","options":["பார்வோனின் பானபாத்திரக்காரரின் தலைவனும் சுயம்பாகிகளின் தலைவனும்","போத்திபாரும் அவன் மனைவியும்","ஓன் பட்டணத்து இரண்டு ஆசாரியர்","அவனுடைய இரண்டு சகோதரர்"]}'::jsonb, 'cup', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k138', 'mcq', 'GEN', 41, 3, null, 2, '0'::jsonb, '{"q":"In Pharaoh''s first dream, what came up out of the river?","options":["Seven fat kine and seven lean kine","Seven ears of corn","Seven great fish","Seven serpents"],"explain":"In the second dream, seven thin ears devoured seven good ears on one stalk."}'::jsonb, '{"q":"பார்வோனின் முதல் சொப்பனத்தில் நதியிலிருந்து ஏறிவந்தவை எவை?","options":["ஏழு கொழுத்த பசுக்களும் ஏழு கேவலமான பசுக்களும்","ஏழு கதிர்கள்","ஏழு பெரிய மீன்கள்","ஏழு சர்ப்பங்கள்"],"explain":"இரண்டாம் சொப்பனத்தில், ஒரே தாளில் வந்த ஏழு நல்ல கதிர்களை ஏழு சாவியான கதிர்கள் விழுங்கின."}'::jsonb, 'cows', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k139', 'mcq', 'GEN', 41, 34, null, 2, '2'::jsonb, '{"q":"What part of the land''s produce was gathered in the seven plenteous years?","options":["The third part","The tenth part","The fifth part","Half"]}'::jsonb, '{"q":"பரிபூரணமான ஏழு வருஷங்களில் தேசத்தின் விளைச்சலில் எந்தப் பங்கு சேர்க்கப்பட்டது?","options":["மூன்றில் ஒரு பங்கு","பத்தில் ஒரு பங்கு","ஐந்தில் ஒரு பங்கு","பாதி"]}'::jsonb, 'sheaves', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k140', 'mcq', 'GEN', 41, 46, null, 2, '1'::jsonb, '{"q":"How old was Joseph when he stood before Pharaoh?","options":["20","30","40","17"]}'::jsonb, '{"q":"பார்வோனுக்கு முன்பாக நின்றபோது யோசேப்புக்கு எத்தனை வயது?","options":["20","30","40","17"]}'::jsonb, 'crown', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k141', 'mcq', 'GEN', 41, 42, null, 2, '2'::jsonb, '{"q":"How did Pharaoh honour Joseph?","options":["Land in Goshen only","A palace and an army","His ring, fine linen, a gold chain and his second chariot","A crown and his own throne"],"explain":"And they cried before him, Bow the knee (41:43)."}'::jsonb, '{"q":"பார்வோன் யோசேப்பை எப்படிக் கனப்படுத்தினான்?","options":["கோசேனில் நிலம் மட்டும்","அரண்மனையும் சேனையும்","தன் முத்திரை மோதிரம், மெல்லிய வஸ்திரம், பொன் சரப்பணி, தன் இரண்டாம் இரதம்","கிரீடமும் தன் சிங்காசனமும்"],"explain":"முழங்காற்படியிடுங்கள் என்று அவனுக்கு முன்பாகக் கூப்பிட்டார்கள் (41:43)."}'::jsonb, 'ring', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k142', 'mcq', 'GEN', 41, 45, null, 2, '1'::jsonb, '{"q":"Who was Joseph''s wife?","options":["Dinah","Asenath, the daughter of the priest of On","Tamar","Zipporah"]}'::jsonb, '{"q":"யோசேப்பின் மனைவி யார்?","options":["தீனாள்","ஓன் பட்டணத்து ஆசாரியனின் மகள் ஆஸ்நாத்","தாமார்","சிப்போராள்"]}'::jsonb, 'crown', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k143', 'mcq', 'GEN', 41, 50, null, 2, '1'::jsonb, '{"q":"When were Joseph''s sons Manasseh and Ephraim born?","options":["After Jacob came to Egypt","Before the years of famine came","During the famine","In the land of Canaan"]}'::jsonb, '{"q":"யோசேப்பின் குமாரராகிய மனாசேயும் எப்பிராயீமும் எப்போது பிறந்தார்கள்?","options":["யாக்கோபு எகிப்துக்கு வந்தபின்","பஞ்ச வருஷங்கள் வருவதற்கு முன்","பஞ்ச காலத்தில்","கானான் தேசத்தில்"]}'::jsonb, 'sheaves', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k144', 'mcq', 'GEN', 41, 51, null, 2, '1'::jsonb, '{"q":"What does the name Manasseh mean?","options":["God hath caused me to be fruitful","God hath made me forget all my toil and all my father''s house","The LORD hath heard","God''s host"]}'::jsonb, '{"q":"மனாசே என்ற பெயரின் அர்த்தம் என்ன?","options":["தேவன் என்னைப் பலுகப்பண்ணினார்","என் எல்லா வருத்தத்தையும் என் தகப்பன் வீட்டையும் தேவன் மறக்கப்பண்ணினார்","கர்த்தர் கேட்டார்","தேவனுடைய சேனை"]}'::jsonb, 'crown', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k145', 'mcq', 'GEN', 41, 52, null, 2, '0'::jsonb, '{"q":"What does the name Ephraim mean?","options":["God hath caused me to be fruitful in the land of my affliction","Son of my right hand","God hath made me forget all my toil","Laughter"]}'::jsonb, '{"q":"எப்பிராயீம் என்ற பெயரின் அர்த்தம் என்ன?","options":["நான் சிறுமைப்பட்ட தேசத்தில் தேவன் என்னைப் பலுகப்பண்ணினார்","என் வலதுகையின் குமாரன்","என் எல்லா வருத்தத்தையும் தேவன் மறக்கப்பண்ணினார்","நகைப்பு"]}'::jsonb, 'crown', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k146', 'mcq', 'GEN', 42, 17, null, 2, '2'::jsonb, '{"q":"For how many days did Joseph put his brothers in ward?","options":["1 day","7 days","3 days","10 days"]}'::jsonb, '{"q":"யோசேப்பு தன் சகோதரரை எத்தனை நாள் காவலில் வைத்தான்?","options":["1 நாள்","7 நாள்","3 நாள்","10 நாள்"]}'::jsonb, 'sacks', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k147', 'mcq', 'GEN', 42, 24, null, 2, '1'::jsonb, '{"q":"Which brother did Joseph bind and keep in Egypt?","options":["Reuben","Simeon","Benjamin","Judah"]}'::jsonb, '{"q":"யோசேப்பு எந்தச் சகோதரனைக் கட்டி எகிப்தில் வைத்தான்?","options":["ரூபன்","சிமியோன்","பென்யமீன்","யூதா"]}'::jsonb, 'sacks', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k148', 'mcq', 'GEN', 42, 37, null, 2, '3'::jsonb, '{"q":"What did Reuben offer to his father as surety for Benjamin?","options":["His own life","All his flocks","20 pieces of silver","His two sons"]}'::jsonb, '{"q":"பென்யமீனுக்காக ரூபன் தன் தகப்பனிடம் எதை உத்தரவாதமாகக் கொடுத்தான்?","options":["தன் உயிரை","தன் மந்தைகள் எல்லாவற்றையும்","20 வெள்ளிக்காசை","தன் இரண்டு குமாரரை"]}'::jsonb, 'sacks', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k149', 'mcq', 'GEN', 43, 9, null, 2, '1'::jsonb, '{"q":"Who became surety for Benjamin the second time?","options":["Levi","Judah","Reuben","Simeon"]}'::jsonb, '{"q":"பென்யமீனுக்காக இரண்டாம் முறை உத்தரவாதம் கொடுத்தவன் யார்?","options":["லேவி","யூதா","ரூபன்","சிமியோன்"]}'::jsonb, 'sacks', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k150', 'mcq', 'GEN', 43, 11, null, 2, '2'::jsonb, '{"q":"What present did Jacob send down to the ruler of Egypt?","options":["Lambs and goats","Wine and bread","Balm, honey, spices, myrrh, nuts and almonds","Gold and silver"]}'::jsonb, '{"q":"எகிப்தின் அதிபதிக்கு யாக்கோபு அனுப்பின வெகுமதி என்ன?","options":["ஆட்டுக்குட்டிகளும் வெள்ளாடுகளும்","திராட்சரசமும் அப்பமும்","பிசின் தைலம், தேன், கந்தவர்க்கம், வெள்ளைப்போளம், தெரபிந்துக் கொட்டை, வாதுமைக் கொட்டை","பொன்னும் வெள்ளியும்"]}'::jsonb, 'donkey', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k151', 'mcq', 'GEN', 43, 33, null, 2, '2'::jsonb, '{"q":"Why did the brothers marvel one at another in Joseph''s house?","options":["They were served Hebrew food","Joseph spoke to them in Hebrew","They were seated by age, from the firstborn to the youngest","Their money was in their sacks"]}'::jsonb, '{"q":"யோசேப்பின் வீட்டில் சகோதரர் ஏன் ஒருவரையொருவர் பார்த்து ஆச்சரியப்பட்டார்கள்?","options":["எபிரெய உணவு பரிமாறப்பட்டது","யோசேப்பு அவர்களோடு எபிரெய பாஷையில் பேசினான்","மூத்தவன் முதல் இளையவன் வரை வயதின்படி உட்காரவைக்கப்பட்டார்கள்","அவர்கள் பணம் சாக்குகளில் இருந்தது"]}'::jsonb, 'loaves', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k152', 'mcq', 'GEN', 43, 34, null, 2, '1'::jsonb, '{"q":"How many times more food was Benjamin given than his brothers?","options":["2 times","5 times","10 times","7 times"]}'::jsonb, '{"q":"சகோதரரைவிட பென்யமீனுக்கு எத்தனை மடங்கு அதிகமாக உணவு கொடுக்கப்பட்டது?","options":["2 மடங்கு","5 மடங்கு","10 மடங்கு","7 மடங்கு"]}'::jsonb, 'loaves', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k153', 'mcq', 'GEN', 45, 1, null, 2, '3'::jsonb, '{"q":"When did Joseph make himself known to his brothers?","options":["After Jacob died","On their very first visit","When Pharaoh told them","After the cup was found in Benjamin''s sack and Judah offered himself in Benjamin''s place"]}'::jsonb, '{"q":"யோசேப்பு எப்போது தன்னைத் தன் சகோதரருக்கு வெளிப்படுத்தினான்?","options":["யாக்கோபு மரித்தபின்","அவர்கள் முதல்முறை வந்தபோதே","பார்வோன் அவர்களுக்குச் சொன்னபோது","பென்யமீனின் சாக்கில் பாத்திரம் கண்டுபிடிக்கப்பட்டு, பென்யமீனுக்குப் பதிலாக யூதா தன்னை ஒப்புக்கொடுத்தபின்"]}'::jsonb, 'cup', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k154', 'mcq', 'GEN', 45, 10, null, 2, '0'::jsonb, '{"q":"In which land of Egypt did Jacob''s family dwell?","options":["Goshen","On","Zoan","Memphis"]}'::jsonb, '{"q":"யாக்கோபின் குடும்பம் எகிப்தில் எந்தத் தேசத்தில் குடியிருந்தது?","options":["கோசேன்","ஓன்","சோவான்","நோப்"]}'::jsonb, 'sheep', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k155', 'mcq', 'GEN', 45, 6, null, 2, '0'::jsonb, '{"q":"How many years of famine were still to come when Joseph revealed himself?","options":["5 years","3 years","7 years","2 years"]}'::jsonb, '{"q":"யோசேப்பு தன்னை வெளிப்படுத்தியபோது இன்னும் எத்தனை வருஷம் பஞ்சம் இருக்கவேண்டியிருந்தது?","options":["5 வருஷம்","3 வருஷம்","7 வருஷம்","2 வருஷம்"]}'::jsonb, 'sacks', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k156', 'mcq', 'GEN', 45, 19, null, 2, '1'::jsonb, '{"q":"What did Joseph send to bring his father''s household down to Egypt?","options":["Ships","Wagons","Chariots of war","Camels"],"explain":"The brothers had gone to buy food on their asses (42:26)."}'::jsonb, '{"q":"தன் தகப்பனின் குடும்பத்தை எகிப்துக்குக் கொண்டுவர யோசேப்பு எதை அனுப்பினான்?","options":["கப்பல்கள்","வண்டிகள்","யுத்த இரதங்கள்","ஒட்டகங்கள்"],"explain":"சகோதரர் தானியம் வாங்கக் கழுதைகளின்மேல் போனார்கள் (42:26)."}'::jsonb, 'wagon', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k157', 'mcq', 'GEN', 45, 22, null, 2, '1'::jsonb, '{"q":"What did Joseph give to Benjamin?","options":["A silver cup","300 pieces of silver and five changes of raiment","A coat of many colours","His signet ring"]}'::jsonb, '{"q":"யோசேப்பு பென்யமீனுக்குக் கொடுத்தது என்ன?","options":["வெள்ளிப் பாத்திரம்","300 வெள்ளிக்காசும் ஐந்து மாற்று வஸ்திரமும்","பலவர்ண அங்கி","தன் முத்திரை மோதிரம்"]}'::jsonb, 'coins', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k158', 'mcq', 'GEN', 45, 23, null, 2, '2'::jsonb, '{"q":"What did Joseph send to his father?","options":["A chariot and horses","Seven wagons of wine","Ten asses with the good things of Egypt and ten she asses with corn, bread and meat","Twenty camels laden with gold"]}'::jsonb, '{"q":"யோசேப்பு தன் தகப்பனுக்கு அனுப்பினது என்ன?","options":["ஒரு இரதமும் குதிரைகளும்","திராட்சரசம் ஏற்றிய ஏழு வண்டிகள்","எகிப்தின் உச்சிதமான பதார்த்தங்களுடன் பத்துக் கழுதைகளும், தானியம், அப்பம், தின்பண்டங்களுடன் பத்துக் கோளிகைக் கழுதைகளும்","பொன் ஏற்றிய இருபது ஒட்டகங்கள்"]}'::jsonb, 'donkey', array['knowledge']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k159', 'mcq', 'GEN', 46, 4, null, 2, '3'::jsonb, '{"q":"Where did God say to Jacob, \"I will go down with thee into Egypt\"?","options":["Hebron","Bethel","Goshen","Beer-sheba"]}'::jsonb, '{"q":"\"நான் உன்னோடேகூட எகிப்துக்கு வருவேன்\" என்று தேவன் யாக்கோபிடம் எங்கே சொன்னார்?","options":["எபிரோன்","பெத்தேல்","கோசேன்","பெயெர்செபா"]}'::jsonb, 'ladder', array['knowledge']::text[], 'published')
