insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k162', 'mcq', 'GEN', 47, 28, null, 2, '3'::jsonb, '{"q":"For how many years did Jacob live in Egypt?","options":["20 years","7 years","40 years","17 years"]}'::jsonb, '{"q":"யாக்கோபு எகிப்தில் எத்தனை வருஷம் உயிரோடிருந்தான்?","options":["20 வருஷம்","7 வருஷம்","40 வருஷம்","17 வருஷம்"]}'::jsonb, 'elder', array['knowledge']::text[], 'published')
