insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k165', 'mcq', 'GEN', 50, 3, null, 2, '0'::jsonb, '{"q":"For how many days did the Egyptians mourn for Jacob?","options":["70 days","7 days","40 days","30 days"]}'::jsonb, '{"q":"எகிப்தியர் யாக்கோபுக்காக எத்தனை நாள் துக்கங்கொண்டாடினார்கள்?","options":["70 நாள்","7 நாள்","40 நாள்","30 நாள்"]}'::jsonb, 'elder', array['knowledge']::text[], 'published')
