insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-k171', 'mcq', '2KI', 11, 3, null, 2, '0'::jsonb, '{"q":"Which two children grew up in the house of the LORD?","options":["Samuel and Joash","Eli and Samuel","David and Solomon","Moses and Aaron"],"explain":"Samuel grew before the LORD (1 Samuel 2:21); Joash was hid in the house of the LORD six years."}'::jsonb, '{"q":"கர்த்தருடைய ஆலயத்தில் வளர்ந்த இரண்டு பிள்ளைகள் யார்?","options":["சாமுவேல், யோவாஸ்","ஏலி, சாமுவேல்","தாவீது, சாலொமோன்","மோசே, ஆரோன்"],"explain":"சாமுவேல் கர்த்தருடைய சந்நிதியில் வளர்ந்தான் (1 சாமு. 2:21); யோவாஸ் ஆறு வருஷம் கர்த்தருடைய ஆலயத்தில் ஒளித்துவைக்கப்பட்டான்."}'::jsonb, 'lamp', array['knowledge']::text[], 'published')
