insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-cn-MAT', 'mcq', 'MAT', 28, null, null, 2, '3'::jsonb, '{"q":"How many chapters does Matthew have?","options":["27","31","24","28"],"explain":"Matthew has 28 chapters. Acts also has 28."}'::jsonb, '{"q":"மத்தேயு புஸ்தகத்தில் எத்தனை அதிகாரங்கள் உள்ளன?","options":["27","31","24","28"],"explain":"மத்தேயு புஸ்தகத்தில் 28 அதிகாரங்கள் உள்ளன. அப்போஸ்தலருடைய நடபடிகள் புஸ்தகத்திலும் 28 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-ch-MRK', 'book', 'MRK', 16, null, null, 2, '3'::jsonb, '{"q":"Which of these books has 16 chapters?","options":["Judges","Nehemiah","Zechariah","Mark"],"explain":"Mark has 16 chapters. Romans, 1 Corinthians also have 16."}'::jsonb, '{"q":"இவற்றில் 16 அதிகாரங்கள் உள்ள புஸ்தகம் எது?","options":["நியாயாதிபதிகள்","நெகேமியா","சகரியா","மாற்கு"],"explain":"மாற்கு புஸ்தகத்தில் 16 அதிகாரங்கள் உள்ளன. ரோமர், 1 கொரிந்தியர் புஸ்தகத்திலும் 16 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-cn-LUK', 'mcq', 'LUK', 24, null, null, 2, '3'::jsonb, '{"q":"How many chapters does Luke have?","options":["22","27","28","24"],"explain":"Luke has 24 chapters. Joshua, 2 Samuel also have 24."}'::jsonb, '{"q":"லூக்கா புஸ்தகத்தில் எத்தனை அதிகாரங்கள் உள்ளன?","options":["22","27","28","24"],"explain":"லூக்கா புஸ்தகத்தில் 24 அதிகாரங்கள் உள்ளன. யோசுவா, 2 சாமுவேல் புஸ்தகத்திலும் 24 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-ch-JHN', 'book', 'JHN', 21, null, null, 2, '3'::jsonb, '{"q":"Which of these books has 21 chapters?","options":["Romans","Revelation","Mark","John"],"explain":"John has 21 chapters. Judges also has 21."}'::jsonb, '{"q":"இவற்றில் 21 அதிகாரங்கள் உள்ள புஸ்தகம் எது?","options":["ரோமர்","வெளிப்படுத்தின விசேஷம்","மாற்கு","யோவான்"],"explain":"யோவான் புஸ்தகத்தில் 21 அதிகாரங்கள் உள்ளன. நியாயாதிபதிகள் புஸ்தகத்திலும் 21 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-cn-ACT', 'mcq', 'ACT', 28, null, null, 2, '1'::jsonb, '{"q":"How many chapters does Acts have?","options":["31","28","25","34"],"explain":"Acts has 28 chapters. Matthew also has 28."}'::jsonb, '{"q":"அப்போஸ்தலருடைய நடபடிகள் புஸ்தகத்தில் எத்தனை அதிகாரங்கள் உள்ளன?","options":["31","28","25","34"],"explain":"அப்போஸ்தலருடைய நடபடிகள் புஸ்தகத்தில் 28 அதிகாரங்கள் உள்ளன. மத்தேயு புஸ்தகத்திலும் 28 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
