insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-ch-COL', 'book', 'COL', 4, null, null, 2, '1'::jsonb, '{"q":"Which of these books has 4 chapters?","options":["Nahum","Colossians","Zephaniah","2 Thessalonians"],"explain":"Colossians has 4 chapters. Ruth, Jonah, Malachi, Philippians, 2 Timothy also have 4."}'::jsonb, '{"q":"இவற்றில் 4 அதிகாரங்கள் உள்ள புஸ்தகம் எது?","options":["நாகூம்","கொலோசெயர்","செப்பனியா","2 தெசலோனிக்கேயர்"],"explain":"கொலோசெயர் புஸ்தகத்தில் 4 அதிகாரங்கள் உள்ளன. ரூத், யோனா, மல்கியா, பிலிப்பியர், 2 தீமோத்தேயு புஸ்தகத்திலும் 4 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-cn-1TH', 'mcq', '1TH', 5, null, null, 2, '0'::jsonb, '{"q":"How many chapters does 1 Thessalonians have?","options":["5","8","7","2"],"explain":"1 Thessalonians has 5 chapters. Lamentations, James, 1 Peter, 1 John also have 5."}'::jsonb, '{"q":"1 தெசலோனிக்கேயர் புஸ்தகத்தில் எத்தனை அதிகாரங்கள் உள்ளன?","options":["5","8","7","2"],"explain":"1 தெசலோனிக்கேயர் புஸ்தகத்தில் 5 அதிகாரங்கள் உள்ளன. புலம்பல், யாக்கோபு, 1 பேதுரு, 1 யோவான் புஸ்தகத்திலும் 5 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-ch-2TH', 'book', '2TH', 3, null, null, 2, '3'::jsonb, '{"q":"Which of these books has 3 chapters?","options":["Malachi","Colossians","Jonah","2 Thessalonians"],"explain":"2 Thessalonians has 3 chapters. Joel, Nahum, Habakkuk, Zephaniah, Titus, 2 Peter also have 3."}'::jsonb, '{"q":"இவற்றில் 3 அதிகாரங்கள் உள்ள புஸ்தகம் எது?","options":["மல்கியா","கொலோசெயர்","யோனா","2 தெசலோனிக்கேயர்"],"explain":"2 தெசலோனிக்கேயர் புஸ்தகத்தில் 3 அதிகாரங்கள் உள்ளன. யோவேல், நாகூம், ஆபகூக், செப்பனியா, தீத்து, 2 பேதுரு புஸ்தகத்திலும் 3 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-cn-1TI', 'mcq', '1TI', 6, null, null, 2, '2'::jsonb, '{"q":"How many chapters does 1 Timothy have?","options":["3","8","6","5"],"explain":"1 Timothy has 6 chapters. Galatians, Ephesians also have 6."}'::jsonb, '{"q":"1 தீமோத்தேயு புஸ்தகத்தில் எத்தனை அதிகாரங்கள் உள்ளன?","options":["3","8","6","5"],"explain":"1 தீமோத்தேயு புஸ்தகத்தில் 6 அதிகாரங்கள் உள்ளன. கலாத்தியர், எபேசியர் புஸ்தகத்திலும் 6 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-ch-2TI', 'book', '2TI', 4, null, null, 2, '2'::jsonb, '{"q":"Which of these books has 4 chapters?","options":["1 Peter","2 Thessalonians","2 Timothy","Habakkuk"],"explain":"2 Timothy has 4 chapters. Ruth, Jonah, Malachi, Philippians, Colossians also have 4."}'::jsonb, '{"q":"இவற்றில் 4 அதிகாரங்கள் உள்ள புஸ்தகம் எது?","options":["1 பேதுரு","2 தெசலோனிக்கேயர்","2 தீமோத்தேயு","ஆபகூக்"],"explain":"2 தீமோத்தேயு புஸ்தகத்தில் 4 அதிகாரங்கள் உள்ளன. ரூத், யோனா, மல்கியா, பிலிப்பியர், கொலோசெயர் புஸ்தகத்திலும் 4 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-cn-TIT', 'mcq', 'TIT', 3, null, null, 2, '0'::jsonb, '{"q":"How many chapters does Titus have?","options":["3","2","4","6"],"explain":"Titus has 3 chapters. Joel, Nahum, Habakkuk, Zephaniah, 2 Thessalonians, 2 Peter also have 3."}'::jsonb, '{"q":"தீத்து புஸ்தகத்தில் எத்தனை அதிகாரங்கள் உள்ளன?","options":["3","2","4","6"],"explain":"தீத்து புஸ்தகத்தில் 3 அதிகாரங்கள் உள்ளன. யோவேல், நாகூம், ஆபகூக், செப்பனியா, 2 தெசலோனிக்கேயர், 2 பேதுரு புஸ்தகத்திலும் 3 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-ch-PHM', 'book', 'PHM', 1, null, null, 2, '2'::jsonb, '{"q":"Which of these books has only one chapter?","options":["Jonah","Haggai","Philemon","Titus"],"explain":"Philemon has 1 chapter. Obadiah, 2 John, 3 John, Jude also have 1."}'::jsonb, '{"q":"இவற்றில் ஒரே ஒரு அதிகாரம் உள்ள புஸ்தகம் எது?","options":["யோனா","ஆகாய்","பிலேமோன்","தீத்து"],"explain":"பிலேமோன் புஸ்தகத்தில் ஒரே ஒரு அதிகாரம் உள்ளது. ஒபதியா, 2 யோவான், 3 யோவான், யூதா புஸ்தகத்திலும் 1 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-cn-HEB', 'mcq', 'HEB', 13, null, null, 2, '2'::jsonb, '{"q":"How many chapters does Hebrews have?","options":["8","12","13","14"],"explain":"Hebrews has 13 chapters. Nehemiah, 2 Corinthians also have 13."}'::jsonb, '{"q":"எபிரெயர் புஸ்தகத்தில் எத்தனை அதிகாரங்கள் உள்ளன?","options":["8","12","13","14"],"explain":"எபிரெயர் புஸ்தகத்தில் 13 அதிகாரங்கள் உள்ளன. நெகேமியா, 2 கொரிந்தியர் புஸ்தகத்திலும் 13 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-ch-JAS', 'book', 'JAS', 5, null, null, 2, '1'::jsonb, '{"q":"Which of these books has 5 chapters?","options":["Joel","James","Ephesians","Colossians"],"explain":"James has 5 chapters. Lamentations, 1 Thessalonians, 1 Peter, 1 John also have 5."}'::jsonb, '{"q":"இவற்றில் 5 அதிகாரங்கள் உள்ள புஸ்தகம் எது?","options":["யோவேல்","யாக்கோபு","எபேசியர்","கொலோசெயர்"],"explain":"யாக்கோபு புஸ்தகத்தில் 5 அதிகாரங்கள் உள்ளன. புலம்பல், 1 தெசலோனிக்கேயர், 1 பேதுரு, 1 யோவான் புஸ்தகத்திலும் 5 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
insert into questions (id, type, book_code, chapter, verse, verse_end, difficulty, answer, en, ta, art, tags, status) values ('kn-cn-1PE', 'mcq', '1PE', 5, null, null, 2, '3'::jsonb, '{"q":"How many chapters does 1 Peter have?","options":["6","4","7","5"],"explain":"1 Peter has 5 chapters. Lamentations, 1 Thessalonians, James, 1 John also have 5."}'::jsonb, '{"q":"1 பேதுரு புஸ்தகத்தில் எத்தனை அதிகாரங்கள் உள்ளன?","options":["6","4","7","5"],"explain":"1 பேதுரு புஸ்தகத்தில் 5 அதிகாரங்கள் உள்ளன. புலம்பல், 1 தெசலோனிக்கேயர், யாக்கோபு, 1 யோவான் புஸ்தகத்திலும் 5 அதிகாரங்கள் உள்ளன."}'::jsonb, 'bookch', array['knowledge','chapters']::text[], 'published')
